-- plans seed
-- Primary subscription plans for all 85 tracked apps.
-- Idempotent: safe to re-run.

on conflict (id) do update set
  name=excluded.name, billing_period=excluded.billing_period,
  base_price_usd=excluded.base_price_usd, is_default=excluded.is_default,
  description=excluded.description, features=excluded.features,
  updated_at=now();

-- Backfill current_prices: set plan_id = default plan for each app
update current_prices cp
set plan_id = p.id
from plans p
where p.app_id = cp.app_id
  and p.is_default = true
  and cp.plan_id is null;
